'use strict';
/* ===== map helpers ===== */
const MAPS=[];S.mapState={};
function mapBox(key,h=520){return`<div class="map-host" data-map="${key}" style="height:${h}px"></div>`}
function mountMaps(){MAPS.forEach(m=>m.destroy());MAPS.length=0;
  $$('#main [data-map]').forEach(el=>{const key=el.dataset.map;const cfg=MAPCFG[key];if(!cfg)return;
    const mv=new MapView(el,{popup:p=>popupHtml(p),gm:pts=>gmFilterUrl(pts,key)});
    MAPS.push(mv);const pts=cfg();mv.setPoints(pts);
    const sig=pts.length+'|'+pts.map(p=>p.id).join(',').slice(0,4000);const st=S.mapState[key];if(st&&st.sig===sig){mv.cx=st.cx;mv.cy=st.cy;mv.z=st.z;mv.draw()}else mv.fit();
    const save=()=>{S.mapState[key]={cx:mv.cx,cy:mv.cy,z:mv.z,sig}};el.addEventListener('pointerup',save);el.addEventListener('wheel',debounce(save,200));el.addEventListener('click',save)});
}
function popupHtml(p){const e=entOf(p.id)||{};const r=e.code?R(e.code):null;const c={lat:p.lat,lng:p.lng};
  return`<div class="pop-t">${esc(p.name)}</div><div class="mut">${esc([e.code,e.kel,e.kec].filter(Boolean).join(' · '))}</div>${p.tag?`<div class="pop-tag" style="color:${p.c}">● ${esc(p.tag)}</div>`:''}${r?`<div class="mut">Sales ${periodLabel(CALC.p,true)}: <b>${fmtS(r.cur)}</b> (${isFinite(r.chg)?sgnPct(r.chg,0):'–'})</div>`:''}
  <div class="pop-a"><button class="btn sm" data-act="mem" data-id="${p.id}">Detail</button><a class="btn sm navy" href="${gmapsPt(c)}" target="_blank" rel="noopener">${IC.pin} Buka di Google Maps</a><a class="btn sm" href="${gmapsNav(c)}" target="_blank" rel="noopener">➜ Navigasi</a>${p.ph?`<a class="btn sm wa" href="${e.id?waLink(e):'#'}" target="_blank" rel="noopener" data-act="wa" data-id="${p.id}">WA</a>`:''}</div>`}
const PIC_COL=['#2a78d6','#eb6834','#1baf7a','#eda100','#e87ba4','#008300','#6250d6','#e34948','#52514e','#86b6ef'];
function picColor(p){const i=D.M.pics.indexOf(p);return i<0?'#a8a69f':PIC_COL[i%PIC_COL.length]}
/* Tombol Google Maps di peta: 1 titik → pin langsung; banyak titik → peta My Maps tim, dibuka tepat di area titik hasil filter */
function gmFilterUrl(pts,key){if(!pts.length)return'';if(pts.length===1)return gmapsPt(pts[0]);
  const m=key==='project'?mmMap(F('project').p||'loy'):(S.mymaps&&S.mymaps.mid?S.mymaps:MYMAPS_DEFAULT);
  const xs=pts.map(p=>p.x).sort((a,b)=>a-b),ys=pts.map(p=>p.y).sort((a,b)=>a-b);const q=(a,f)=>a[Math.floor(f*(a.length-1))];const lo=pts.length>50?.02:0;
  const x0=q(xs,lo),x1=q(xs,1-lo),y0=q(ys,lo),y1=q(ys,1-lo);const z=Math.max(10,Math.min(17,Math.floor(Math.log2(Math.min(1000/Math.max(x1-x0,1e-7),650/Math.max(y1-y0,1e-7))))));
  return`https://www.google.com/maps/d/edit?mid=${m.mid}&usp=sharing&ll=${unY((y0+y1)/2).toFixed(6)}%2C${unX((x0+x1)/2).toFixed(6)}&z=${z}`}
const MAPCFG={
  wilayah:()=>{const f=F('wilayah');return CALC.rows.filter(r=>r.m.coord&&(!f.kec||(r.m.dist||'BELUM TERISI')===f.kec)&&(!f.st||r.st===f.st)).map(r=>({id:r.m.id,name:r.m.name,lat:r.m.lat,lng:r.m.lng,c:ST[r.st].c,tag:ST[r.st].l,ph:r.m.phone}))},
  project:()=>(S._projRows||[]).filter(e=>coordOf(e)).map(e=>{const c=coordOf(e),z=e.src==='ZB',s=z?zbSt(e):statusOf(e);return{id:e.id,name:e.name,lat:c.lat,lng:c.lng,c:z?ZB.COL[s]:PIN_COL[FU_CLS[s]],r:6,tag:s+(picOf(e)?' · PIC '+picLbl(picOf(e)):''),ph:phoneOf(e)}}),
  drawer:()=>{const e=S.drawerId&&entOf(S.drawerId);const c=e&&coordOf(e);return c?[{id:e.id,name:e.name,lat:c.lat,lng:c.lng,c:'#c8102e'}]:[]},
};

/* ===== WILAYAH ===== */
function vWilayah(){const f=F('wilayah');const C=CALC;const by={};
  C.rows.forEach(r=>{const k=r.m.dist||'BELUM TERISI';const o=by[k]=by[k]||{k,n:0,act:0,cur:0,prev:0,turun:0,sleeper:0,city:r.m.city};o.n++;if(r.cur>0)o.act++;o.cur+=r.cur;o.prev+=r.prevAdj;if(r.st==='turun')o.turun++;if(r.st==='sleeper')o.sleeper++});
  let arr=Object.values(by);if(f.city)arr=arr.filter(o=>o.city===f.city);const sk=f.ws||'cur';arr.sort((a,b)=>sk==='chg'?(a.cur/(a.prev||1))-(b.cur/(b.prev||1)):b[sk]-a[sk]);
  const kel=f.kec?Object.values(C.rows.filter(r=>(r.m.dist||'BELUM TERISI')===f.kec).reduce((a,r)=>{const k=r.m.vil||'-';const o=a[k]=a[k]||{k,n:0,act:0,cur:0,prev:0,turun:0};o.n++;if(r.cur>0)o.act++;o.cur+=r.cur;o.prev+=r.prevAdj;if(r.st==='turun')o.turun++;return a},{})).sort((a,b)=>b.cur-a.cur):null;
  const cities=countBy(D.mem,m=>m.city||'(kosong)');
  return pageHead('Analisis wilayah',`Kontribusi per kecamatan & sebaran titik member · ${periodNote()}`,`<button class="btn" data-act="x-xls">${IC.xls} Excel</button>`)
  +`<div class="fbar">${selectF('wilayah.city','Kota/kab',[{v:'',l:'Semua'},...Object.entries(cities).sort((a,b)=>b[1]-a[1]).map(([k,n])=>({v:k,l:`${title(k)} (${n})`}))],f.city)}${selectF('wilayah.ws','Urutkan',[{v:'cur',l:'Sales terbesar'},{v:'n',l:'Member terbanyak'},{v:'turun',l:'Member turun terbanyak'},{v:'sleeper',l:'Sleeper terbanyak'},{v:'chg',l:'Penurunan % terbesar'}],sk)}${selectF('wilayah.st','Titik di peta',[{v:'',l:'Semua status'},...ST_ORDER.map(k=>({v:k,l:ST[k].l}))],f.st)}${f.kec?`<span class="tag red">Kecamatan: ${esc(title(f.kec))} <button class="lnk" data-act="fset" data-v="wilayah.kec" data-k="">✕</button></span>`:''}</div>
  <div class="grid g11"><div class="card p0"><div class="tbl-wrap flat" style="max-height:600px"><table class="tbl"><thead><tr><th>${f.kec?'Kelurahan':'Kecamatan'}</th><th class="num">Member</th><th class="num">Aktif</th><th class="num">Sales</th><th class="num">vs pemb.</th><th class="num">Turun</th>${f.kec?'':'<th class="num">Sleeper</th>'}</tr></thead><tbody>
   ${(kel||arr).map(o=>{const ch=o.prev?o.cur/o.prev-1:null;return`<tr class="click" ${kel?'':`data-act="fset" data-v="wilayah.kec" data-k="${esc(o.k)}"`}><td><b>${esc(title(o.k))}</b>${kel?'':`<div class="mut">${esc(title(o.city))}</div>`}</td><td class="num">${fmtN(o.n)}</td><td class="num">${fmtN(o.act)}<div class="mut">${pct(o.act/o.n,0)}</div></td><td class="num">${fmtS(o.cur)}</td><td class="num"><span class="${ch<0?'neg':'pos'}">${ch==null?'–':sgnPct(ch,0)}</span></td><td class="num">${fmtN(o.turun)}</td>${kel?'':`<td class="num">${fmtN(o.sleeper)}</td>`}</tr>`}).join('')}</tbody></table></div></div>
  <div class="card p0">${mapBox('wilayah',600)}</div></div>
  <div class="legend mt">${ST_ORDER.map(k=>`<span><i style="background:${ST[k].c};border-radius:50%"></i>${ST[k].l}</span>`).join('')}<span class="mut">· Klik titik untuk detail, tahan Shift + tarik kotak untuk menambah ke rute</span></div>`;
}

/* ===== PETA & RUTE ===== */
const NO_PIC='__none';
/* ===== Peta titik project: hanya member hasil filter, ketuk pin → Google Maps ===== */
const PIN_COL={neu:'#c8102e',warn:'#eda100',serious:'#ec835a',good:'#0ca30c',crit:'#52514e'}; // kontras di atas peta
function projMapCard(rows){const f=F('project');const pts=rows.filter(e=>coordOf(e)),noC=rows.length-pts.length;
  if(f.nomap)return`<div style="margin:0 0 12px"><button class="btn sm" data-act="fset" data-v="project.nomap" data-k="">${IC.pin} Tampilkan peta titik (${fmtN(pts.length)})</button></div>`;
  const zb=(f.p||'loy')==='zb';const st=countBy(pts,zb?zbSt:statusOf);
  return`<div class="card p0" style="margin:0 0 12px"><div class="card-h" style="padding:12px 14px 8px;margin:0"><div><h3>Peta titik · ${fmtN(pts.length)} member</h3><p class="sub" style="margin:0">Sesuai filter di atas${noC?` · ${fmtN(noC)} member belum punya titik`:''}. Ketuk pin → <b>Buka di Google Maps</b>.</p></div>
   <button class="btn sm ghost" data-act="fset" data-v="project.nomap" data-k="1">Sembunyikan peta</button></div>
   ${pts.length?`${mapBox('project',400)}<div class="legend" style="padding:8px 14px 12px">${(zb?ZB.ST:FU_ST).filter(s=>st[s]).map(s=>`<span><i style="background:${zb?ZB.COL[s]:PIN_COL[FU_CLS[s]]}"></i>${esc(s)} ${fmtN(st[s])}</span>`).join('')}</div>`:'<div class="empty">Tidak ada member bertitik untuk filter ini.</div>'}</div>`}
/* ===== Peta Google My Maps tim =====
   Link disimpan di database (settings/mymaps, hanya pemilik yang bisa mengubah); tanpa database dipakai link bawaan.
   Lapisan per project dicatat dari isi peta saat link dipasang (19 Nov 2026) — hanya ditampilkan untuk peta yang sama. */
const MYMAPS_DEFAULT={mid:'1aqIg2yBLIu5rroWrRlYAaDwdaLrEFW8',name:'PROJECT NOVEMBER 2026'};
const MYMAPS_LAYERS={'1aqIg2yBLIu5rroWrRlYAaDwdaLrEFW8':{loy:['TARGETAN MM NOVEMBER 2026'],map:['Member Kelurahan Air Dingin Pekanbaru','Member Kelurahan Air Putih Pekanbaru'],svy:['REG_BELUM AKTIVASI SUDAH ACC (1)','HOR_BELUM AKTIVASI SUDAH ACC'],klik:['SLEEPERS KLIK SETELAH ONGKIR NAIK (PROJECT KLIK)'],lms:['KLIK_Loyalty Sleeper November 2026','REG_Loyalty Sleeper November 2026','HOR_Loyalty Sleeper November 2026']}};
const mmMid=u=>{const m=/[?&]mid=([A-Za-z0-9_-]{10,})/.exec(String(u||''));return/^https:\/\/(www\.)?google\.[a-z.]+\/maps\/d\//.test(String(u||''))&&m?m[1]:null};
const mmViewer=mid=>`https://www.google.com/maps/d/edit?mid=${mid}&usp=sharing`;
/* peta untuk project: link khusus project → link semua project → bawaan */
function mmMap(P){const s=S.mymaps||{};const pm=s.p&&s.p[P];if(pm&&pm.mid)return pm;if(s.mid)return s;return MYMAPS_DEFAULT}
function mymapsLinkBtn(P){const m=mmMap(P);const ly=(MYMAPS_LAYERS[m.mid]||{})[P]||[];
  return`<a class="btn navy" href="${mmViewer(m.mid)}" target="_blank" rel="noopener" data-tip="${esc(ly.length?'Lapisan untuk project ini: '+ly.join(' · '):'Peta My Maps tim')}">🗺 My Maps tim (semua titik)</a>${isOwner()?`<button class="btn sm ghost" data-act="mm-edit" data-tip="Ganti link peta My Maps (khusus pemilik)">✎ Link peta</button>`:''}`}
function mymapsLayerNote(P){const m=mmMap(P);const ly=(MYMAPS_LAYERS[m.mid]||{})[P]||[];
  return ly.length?`<div class="small muted" style="margin:-4px 0 8px">🗺 Di peta My Maps, nyalakan lapisan: <b>${ly.map(esc).join('</b> · <b>')}</b></div>`:''}
function mymapsEditModal(){const P=F('project').p||'loy';const s=S.mymaps||{};const all=s.mid?s:MYMAPS_DEFAULT;const pp=(s.p&&s.p[P])||{};
  modal('Link peta Google My Maps',`<p class="small muted">Tempel link dari tombol <i>Bagikan</i> di My Maps. Setel berbagi ke <b>"Siapa saja yang memiliki link dapat melihat"</b> (atau bagikan ke akun advisor) agar tim bisa membukanya.</p>
   <label class="sel" style="width:100%"><span>Peta untuk semua project</span><input class="inp" id="mmAll" value="${esc(mmViewer(all.mid))}" style="width:100%"></label>
   <label class="sel mt" style="width:100%"><span>Nama peta</span><input class="inp" id="mmName" value="${esc(all.name||'')}" style="width:100%"></label>
   <label class="sel mt" style="width:100%"><span>Link khusus ${esc(PROJ[P].n)} · ${esc(PROJ[P].t)} (opsional, kosongkan bila sama)</span><input class="inp" id="mmP" value="${esc(pp.mid?mmViewer(pp.mid):'')}" style="width:100%"></label>`,
   {okLbl:'Simpan',ok:async b=>{const a=$('#mmAll',b).value.trim(),pv=$('#mmP',b).value.trim();const ma=mmMid(a),mp=pv?mmMid(pv):null;
     if(!ma){toast('Link peta tidak dikenali — harus link google.com/maps/d/… yang berisi mid=');return false}if(pv&&!mp){toast('Link khusus project tidak dikenali');return false}
     const doc={mid:ma,name:$('#mmName',b).value.trim().slice(0,80),p:{...((S.mymaps||{}).p||{})},at:new Date().toISOString()};if(mp)doc.p[P]={mid:mp};else delete doc.p[P];if(S.uid)doc.by=S.uid;
     if(S.db){try{await S.db.doc('settings/mymaps').set(doc)}catch(e){toast('Gagal simpan: '+(e.code||e.message));return false}}else toast('Database tidak tersedia — link hanya berlaku di browser ini sampai dimuat ulang');
     S.mymaps=doc;rerender();toast('Link peta disimpan untuk seluruh tim')}})}
/* Rute Google Maps dari titik hasil filter: urut terdekat (berantai dari toko IGR), maks 10 titik per tautan
   (batas Google Maps). Titik awal = lokasi HP saat tautan dibuka di Google Maps. */
const GR_SIZES=[5,8,10];
function nearChain(pts,start){const rest=[...pts],out=[];let cur=start;while(rest.length){let bi=0,bd=1e9;rest.forEach((p,i)=>{const d=distKm(cur,p);if(d<bd){bd=d;bi=i}});cur=rest.splice(bi,1)[0];out.push(cur)}return out}
function routePts(rows){return nearChain(rows.map(e=>{const c=coordOf(e);return c?{id:e.id,name:e.name,lat:c.lat,lng:c.lng}:null}).filter(Boolean),PKU)}
function gmapsRouteLink(g){const d=g[g.length-1];const w=g.slice(0,-1).map(p=>`${p.lat},${p.lng}`).join('|');
  return`https://www.google.com/maps/dir/?api=1&destination=${d.lat},${d.lng}${w?`&waypoints=${encodeURIComponent(w)}`:''}&travelmode=driving`}
const grSize=()=>GR_SIZES.includes(+F('project').rsize)?+F('project').rsize:10;
function routeGroups(rows){const pts=routePts(rows),z=grSize(),out=[];for(let i=0;i<pts.length;i+=z)out.push(pts.slice(i,i+z));return out}
function projRouteBtn(rows){const pts=routePts(rows),n=pts.length;
  if(!n)return'';
  if(n===1)return`<a class="btn navy" href="${gmapsNav(pts[0])}" target="_blank" rel="noopener" data-tip="Navigasi ke ${esc(pts[0].name)}">🧭 Rute Google Maps (1 titik)</a>`;
  if(n<=10&&n<=grSize())return`<a class="btn navy" href="${gmapsRouteLink(pts)}" target="_blank" rel="noopener" data-tip="${n} titik hasil filter, urut terdekat · mulai dari lokasi HP">🧭 Rute Google Maps (${n} titik)</a>`;
  return`<button class="btn navy" data-act="proj-route" data-tip="${fmtN(n)} titik · dibagi per ${grSize()} titik (batas Google Maps maks 10 titik per rute)">🧭 Rute Google Maps (${fmtN(n)} titik)</button>`}
function projRouteHtml(){const g=routeGroups(S._projRows||[]),z=grSize(),n=g.reduce((a,x)=>a+x.length,0);
  return`<div class="card-h" style="margin:0 0 8px"><span class="small"><b>${fmtN(n)} titik</b> hasil filter · ${g.length} rute · urut terdekat</span><label class="sel row"><span>Titik per rute</span><select data-act="rsize">${GR_SIZES.map(v=>`<option ${v===z?'selected':''}>${v}</option>`).join('')}</select></label></div>
   <div class="list">${g.map((x,i)=>`<div class="li"><div style="flex:1;min-width:0"><b>Rute ${i+1}</b> <span class="mut">· titik ${i*z+1}–${i*z+x.length}</span><div class="mut small clamp">${esc(x.map(p=>p.name).join(' → '))}</div></div><a class="btn sm navy" href="${gmapsRouteLink(x)}" target="_blank" rel="noopener">🧭 Buka</a></div>`).join('')}</div>
   <p class="small muted mt">Google Maps memulai dari lokasi HP Anda, lalu tekan <b>Mulai</b> untuk navigasi.</p>`}
function projRouteModal(){const bg=modal('Rute Google Maps',`<div id="prm">${projRouteHtml()}</div>`,{wide:true});
  bg.addEventListener('change',e=>{if(e.target.dataset.act==='rsize'){F('project').rsize=+e.target.value;$('#prm',bg).innerHTML=projRouteHtml();rerender()}})}
/* PIC yang benar-benar ada di sekumpulan baris (project / lapisan peta) */
function picsIn(ents){return[...new Set(ents.filter(Boolean).map(picOf).filter(Boolean))].sort()}
/* ===== PROJECT ===== */
function vProject(){const f=F('project');const P=f.p||'loy';f.seg=f.seg||{};const segK=f.seg[P]||(P==='klik'||P==='loy'||P==='zb'?'ALL':'REGULER');const sub=f.sub||'slp';
  const cnt={loy:D.M.loy.members.length,map:projRows('map').length,svy:projRows('svy').length,klik:D.M.slp.rows.filter(r=>!r.back).length+projRows('klik',{sub:'turun'}).length+projRows('klik',{sub:'map'}).length,lms:D.M.lms.rows.length,zb:projRows('zb').length};
  let h=pageHead('Project member merah','Target, mapping, aktivasi dan Klik · PIC, status & catatan tersimpan untuk seluruh tim','');
  h+=`<div class="proj-nav">${Object.entries(PROJ).map(([k,v])=>`<button class="proj-card ${P===k?'on':''}" data-act="proj" data-k="${k}"><span class="eyebrow red">${v.n}</span><span class="pt">${v.t}</span><span class="pc">${fmtN(cnt[k])}</span><span class="pd">${v.d}</span></button>`).join('')}</div>`;
  const info={zb:`<b>Target: semua ${fmtN(projRows('zb').length)} member tahu lolos undangan & datang Minggu 29 Nov 2026.</b> Urutan kerja admin: 1) <b>▶ WA undangan berurutan</b> (pesan sudah terisi, status otomatis "WA terkirim"); 2) belum membalas dalam 1×24 jam → <b>Telepon</b>; 3) nomor tidak aktif / tanpa nomor → "Perlu didatangi": buka titik atau <b>Cari alamat</b> di Google Maps, serahkan ke advisor terdekat; 4) Sabtu 28 Nov tombol berubah jadi <b>Pengingat H-1</b>; 5) Minggu 29 Nov tandai "Hadir 29 Nov". Member luar kota cukup lewat WA/telepon.`,loy:`Target = pembulatan estimasi growth 35% dari sales non-rokok September; hadiah Indomie Goreng Plus (ctn). Status dari proyeksi akhir bulan (asumsi target 1–${D.M.loy.dim} Nov). Data per ${fmtD(D.M.loy.asOf)}.`,map:'Fokus Air Dingin & Air Putih. Penolakan karena belanja sedikit / toko kecil otomatis juga masuk Project Klik. Segmen ditebak dari nama toko — koreksi di kolom Segmen.',svy:'Pendaftar ACC/OK yang belum tercatat ambil kartu. PIC = surveyor. Segmen dari keterangan survey.',klik:'Sub 1: member yang belum belanja lagi sejak 1 Okt (ongkir naik) — otomatis "Berhasil" bila sudah belanja lagi menurut file atau data sales master. Sub 2: semua toko kecil — hasil mapping, ACC survey toko kecil, dan RKM apa pun (belum aktivasi, sleeper, dll.) yang menyebut toko sepi / modal kurang / belanja sedikit. Dikunjungi tim Klik & Ahmad (SPV Klik); status kunjungan hanya dari RKM mereka. Sub 3: member Klik yang belanjanya turun September → Oktober; target kembali ke level September (proyeksi November dari data terbaru).',lms:`Periode promo 3–31 November 2026 · maksimal 1x per member (di luar item larangan) · member sleeper yang kembali belanja ≥ ${fmtRp(LMS.min)} dapat ${fmtN(LMS.poin)} poin IGR. Status kembali dihitung dari data sales November (tanggal ≥ 3); nilai ≥ Rp1 jt adalah total November — cek struk tunggal sebelum memberi poin.`}[P];
  h+=`<div class="alert">${info}</div>`;
  let base;if(P==='klik'){base=projRows('klik',{sub});}else base=projRows(P);
  const segC=countBy(base,segOf);
  h+=`<div class="fbar mt">`;
  if(P==='klik')h+=`<div class="seg-t">${[['slp','Belum belanja sejak 1 Okt',D.M.slp.rows.length],['turun','Belanja turun Sep→Okt',projRows('klik',{sub:'turun'}).length],['map','Toko kecil (mapping, survey & RKM)',projRows('klik',{sub:'map'}).length]].map(([k,l,n])=>`<button class="${sub===k?'on':''}" data-act="fset" data-v="project.sub" data-k="${k}">${l} <b>${n}</b></button>`).join('')}</div>`;
  h+=`<div class="seg-t">${['ALL',...SEGS].map(s=>`<button class="${segK===s?'on':''}" data-act="pseg" data-k="${s}">${s==='ALL'?'Semua':SEG_LBL[s]} <b>${s==='ALL'?base.length:(segC[s]||0)}</b></button>`).join('')}</div>`;
  if(P==='lms'){const jc=countBy(base.filter(r=>segK==='ALL'||segOf(r)===segK),r=>r.jenis);h+=`<div class="seg-t">${[['','Semua jenis'],...LMS.JENIS.map(j=>[j,title(j)])].map(([k,l])=>`<button class="${(f.jenis||'')===k?'on':''}" data-act="fset" data-v="project.jenis" data-k="${k}">${l} <b>${k?jc[k]||0:Object.values(jc).reduce((a,b)=>a+b,0)}</b></button>`).join('')}</div>${selectF('project.lst','Status promo',[{v:'',l:'Semua'},{v:'no',l:'Belum kembali'},{v:'lt',l:'Kembali < Rp1 jt'},{v:'ok',l:'Kembali ≥ Rp1 jt'}],f.lst)}`}
  if(P==='map')h+=`<div class="seg-t">${[['2W','Air Dingin + Air Putih'],['AIR DINGIN','Air Dingin'],['AIR PUTIH','Air Putih']].map(([k,l])=>`<button class="${(f.wil||'2W')===k?'on':''}" data-act="fset" data-v="project.wil" data-k="${k}">${l}</button>`).join('')}</div>${selectF('project.cat','Hasil',[{v:'',l:'Semua'},...CAT_ORDER.map(k=>({v:k,l:CAT[k].l}))],f.cat)}`;
  h+=`</div>`;
  let rows=segK==='ALL'?base:base.filter(r=>segOf(r)===segK);
  if(P==='map'&&f.wil&&f.wil!=='2W'&&f.wil!=='ALL')rows=rows.filter(r=>r.wil===f.wil);if(P==='map'&&f.cat)rows=rows.filter(r=>r.cat===f.cat);
  if(P==='lms'){if(f.jenis)rows=rows.filter(r=>r.jenis===f.jenis);if(f.lst)rows=rows.filter(r=>f.lst==='no'?!r.back:f.lst==='ok'?r.eligible:r.back&&!r.eligible)}
  S._projPics=picsIn(base);if(f.pic&&f.pic!==NO_PIC&&!S._projPics.includes(f.pic))f.pic='';if(!f.pic||f.pic===NO_PIC)f.vis='';
  const picC=countBy(rows,r=>picOf(r)||NO_PIC);
  const visBase=rows;
  if(P==='zb'&&f.zst)rows=rows.filter(r=>zbSt(r)===f.zst);if(P!=='zb'&&f.st)rows=rows.filter(r=>statusOf(r)===f.st);if(f.pic)rows=rows.filter(r=>(picOf(r)||NO_PIC)===f.pic);if(f.vis)rows=rows.filter(r=>!!visitOf(r)===(f.vis==='y'));
  if(f.q){const q=f.q.toLowerCase();rows=rows.filter(r=>[r.name,r.code,r.kel,r.addr,picOf(r),r.alasan,fuOf(r.id).note].join(' ').toLowerCase().includes(q))}
  rows=projSort(P,sub,rows);S._projRows=rows;
  h+=`<div class="pic-bar-h"><span class="lbl">PIC ${esc(PROJ[P].n)}</span><div class="seg-t">${[['','Semua',Object.values(picC).reduce((x,y)=>x+y,0)],...Object.keys(picC).filter(k=>k!==NO_PIC).sort().map(k=>[k,picLbl(k),picC[k]]),...(picC[NO_PIC]?[[NO_PIC,'Tanpa PIC',picC[NO_PIC]]]:[])].map(([k,l,n])=>`<button class="${(f.pic||'')===k?'on':''}" data-act="ppic" data-k="${esc(k)}">${esc(l)} <b>${fmtN(n)}</b></button>`).join('')}</div></div>`;
  if(P!=='zb')h+=visitCard(visBase);
  h+=projStats(P,sub,rows);
  h+=`<div class="fbar"><input class="search" placeholder="Cari nama, kode, kelurahan, catatan…" data-act="fq" data-v="project" value="${esc(f.q||'')}">${P==='zb'?selectF('project.zst','Status undangan',[{v:'',l:'Semua'},...ZB.ST.map(s=>({v:s,l:s}))],f.zst)+`<button class="btn wa" data-act="zb-queue">▶ ${TODAY>=ZB.h1?'Pengingat H-1':'WA undangan'} berurutan</button>`+(isOwner()?'<button class="btn sm ghost" data-act="zb-evt">✎ Detail acara</button>':''):selectF('project.st','Follow-up',[{v:'',l:'Semua'},...FU_ST.map(s=>({v:s,l:s}))],f.st)}<span class="sp"></span>
   <button class="btn" data-act="x-xls">${IC.xls} Excel</button><button class="btn" data-act="x-ppt">${IC.ppt} PPT project</button>${projRouteBtn(rows)}${mymapsLinkBtn(P)}<button class="btn" data-act="wa-tpl">Template WA</button><button class="btn" data-act="list-adv">${IC.wa} Kirim daftar ke advisor</button>${P==='map'||(P==='klik'&&sub==='map')?'<button class="btn pri" data-act="form" data-k="map">✎ Isi Get Member</button>':'<button class="btn pri" data-act="form" data-k="rkm">✎ Isi RKM</button>'}</div>
   ${mymapsLayerNote(P)}<div class="small muted" style="margin:-4px 0 8px">${rows.length} baris · ${rows.filter(r=>coordOf(r)).length} punya titik · ${rows.filter(r=>phoneOf(r)).length} punya nomor WA</div>`;
  h+=projMapCard(rows);
  h+=projTable(P,sub,rows);return h;
}
/* Kunjungan RKM 1 Nov – RKM terakhir: hanya tampil setelah satu PIC dipilih */
function visitCard(rows){const f=F('project');const x=visitIdx();if(!f.pic||f.pic===NO_PIC||!x.last)return'';
  const mine=rows.filter(r=>(picOf(r)||NO_PIC)===f.pic);if(!mine.length)return'';const v=mine.filter(r=>visitOf(r)).length,n=mine.length,q=v/n;
  const b=(k,l,c,cls)=>`<button class="vis-b ${cls} ${(f.vis||'')===k?'on':''}" data-act="pvis" data-v="${k}"><b>${fmtN(c)}</b><span>${l}</span></button>`;
  return`<div class="card vis-card" id="visCard"><div class="vis-h"><div><span class="eyebrow red">Kunjungan RKM ${esc(picLbl(f.pic))}</span><div class="small muted">Tanggal RKM 1 Nov – ${fmtD(toDate(x.last))} · ${pct(q,0)} dari ${fmtN(n)} member</div></div>
   <div class="prog sm vis-p"><div style="width:${Math.round(q*100)}%;background:${q>=.8?'#0ca30c':q>=.4?'#eda100':'#d03b3b'}"></div></div></div>
   <div class="vis-row">${b('','Semua member',n,'')}${b('y','Sudah dikunjungi',v,'pos')}${b('n','Belum dikunjungi',n-v,'neg')}</div></div>`}
/* Status kunjungan & catatan dari RKM (1 Nov – RKM terakhir); belum dikunjungi → tombol isi RKM */
function visCells(r){const v=visitOf(r);
  if(v)return`<td><span class="tag good">✓ Sudah dikunjungi</span><div class="mut small">${fmtD(toDate(v.date))}${v.pic?' · '+esc(picLbl(U(v.pic))):''}</div></td><td class="small vis-note" data-tip="${esc([v.issues,v.notes].filter(Boolean).join(' — ').slice(0,400))}">${esc(rkmBrief(v))}</td>`;
  const gm=r.src==='MAP'&&!r.klik;
  return`<td><button class="btn sm pri" data-act="form" data-k="${gm?'map':'rkm'}" data-id="${r.id}" data-tip="Buka Google Form ${gm?'Get Member':'RKM'} yang sudah terisi data ${gm?'toko':'member'} ini">✎ Isi ${gm?'Get Member':'RKM'}</button></td><td><textarea class="inp" data-act="fu" data-k="note" data-id="${r.id}" rows="1" placeholder="kendala, janji, hasil">${esc(fuOf(r.id).note||'')}</textarea></td>`}
function projSort(P,sub,rows){const f=F('project');const k=f.sort;if(!k)return rows;const d=f.dir||1;const g={name:r=>r.name.toLowerCase(),ratio:r=>r.ratio,ach:r=>r.ach,gap:r=>r.gapDay,chg:r=>r.chg,ts:r=>r.ts?+r.ts:0,nov:r=>r.novGross,age:r=>r.age??0,last:r=>r.last?+r.last:0,kgo:r=>r.kgo,fu:r=>FU_ST.indexOf(statusOf(r)),pic:r=>picOf(r),vis:r=>(visitOf(r)||{}).date||'',zst:r=>ZB.ST.indexOf(zbSt(r))}[k];if(!g)return rows;return[...rows].sort((a,b)=>{const x=g(a),y=g(b);return(x>y?1:x<y?-1:0)*d})}
function picProgress(rows){const pace=D.M.loy.elapsed/D.M.loy.dim;const g={};rows.forEach(m=>{const p=picOf(m)||'-';g[p]=g[p]||{t:0,a:0,n:0,ok:0};g[p].t+=m.target;g[p].a+=m.ach;g[p].n++;if(m.stc==='good')g[p].ok++});
  const ks=Object.keys(g).sort((x,y)=>g[y].a/(g[y].t||1)-g[x].a/(g[x].t||1));
  return`<div class="card mt" id="picProg"><div class="card-h"><h3>Progres per PIC</h3><span class="mut">garis = pace hari ke-${D.M.loy.elapsed} (${pct(pace,0)})</span></div>${ks.map(p=>{const r=g[p].t?g[p].a/g[p].t:0;const c=r>=pace?'#0ca30c':r>=pace*.8?'#eda100':'#d03b3b';
    return`<div class="pic-row"><button class="lnk" data-act="fset" data-v="project.pic" data-k="${esc(p)}">${esc(p==='-'?'Tanpa PIC':picLbl(p))}</button><div class="pic-bar"><i style="width:${Math.min(100,r*100)}%;background:${c}"></i><u style="left:${Math.min(100,pace*100)}%"></u></div><span class="num">${pct(r,0)} · ${g[p].ok}/${g[p].n} on track</span></div>`}).join('')}</div>`}
function projStats(P,sub,rows){if(P==='zb')return zbStats(rows);const st=countBy(rows,statusOf);const n=rows.length||1;let k='',extra='';
  if(P==='loy'){const t=sumBy(rows,m=>m.target),a=sumBy(rows,m=>m.ach),p=sumBy(rows,m=>m.proj);extra=picProgress(rows);k=kpiCard({l:'Capai vs target',v:pct(t?a/t:0,0),note:`${fmtS(a)} / ${fmtS(t)} · pace ${pct(D.M.loy.elapsed/D.M.loy.dim,0)}`,accent:'red'})+kpiCard({l:'Proyeksi akhir bulan',v:pct(t?p/t:0,0),note:`${rows.filter(m=>m.stc==='good').length} on track · hadiah ${sumBy(rows.filter(m=>m.stc==='good'),m=>m.hadiah)} ctn`})}
  else if(P==='map'){const ok=rows.filter(r=>r.cat==='BERHASIL').length,kl=rows.filter(r=>r.cat==='KLIK').length;k=kpiCard({l:'Berhasil get member',v:fmtN(ok),note:`${pct(ok/n,0)} dari ${rows.length} toko`,accent:'red'})+kpiCard({l:'Diarahkan ke Klik',v:fmtN(kl),note:'belanja sedikit / toko kecil',act:'data-act="fset" data-v="project.cat" data-k="KLIK"'})}
  else if(P==='svy'){const o=rows.filter(r=>r.age>30).length;k=kpiCard({l:'Belum aktivasi',v:fmtN(rows.length),note:`${o} menunggu > 30 hari`,accent:'red'})+kpiCard({l:'Rata-rata menunggu',v:Math.round(sumBy(rows,r=>r.age)/n)+' hari',note:'sejak tanggal daftar'})}
  else if(P==='lms'){const b=rows.filter(r=>r.back).length,el=rows.filter(r=>r.eligible).length;k=kpiCard({l:'Kembali belanja (≥ 3 Nov)',v:fmtN(b),note:`${pct(b/n,0)} dari ${fmtN(rows.length)} sleeper · ${fmtS(sumBy(rows,r=>r.novGross))} omzet Nov`,accent:'red',act:'data-act="fset" data-v="project.lst" data-k="lt"'})+kpiCard({l:'Layak 10.000 poin',v:fmtN(el),note:`≥ Rp1 jt · total ${fmtN(el*LMS.poin)} poin`,act:'data-act="fset" data-v="project.lst" data-k="ok"'})}
  else if(P==='klik'&&sub==='turun'){const pl=rows.filter(r=>r.ktSt==='pulih').length,tu=rows.filter(r=>r.ktSt==='turun').length;k=kpiCard({l:'Penurunan Sep → Okt',v:fmtS(sumBy(rows,r=>r.drop)),note:`${fmtN(rows.length)} member Klik · Sept ${fmtS(sumBy(rows,r=>r.sSep))} → Okt ${fmtS(sumBy(rows,r=>r.sOkt))}`,accent:'red'})+kpiCard({l:'Proyeksi November',v:fmtS(sumBy(rows,r=>r.novProj)),note:`${fmtN(pl)} sudah pulih ≥ Sept · ${fmtN(tu)} masih turun`})}
  else if(sub==='slp'){const b=rows.filter(r=>r.back).length;k=kpiCard({l:'Belum belanja lagi',v:fmtN(rows.length-b),note:`${b} sudah kembali belanja`,accent:'red'})+kpiCard({l:'Rata-rata tidak belanja',v:Math.round(sumBy(rows.filter(r=>!r.back),r=>r.days)/Math.max(1,rows.length-b))+' hari',note:'sejak belanja terakhir'})}
  else k=kpiCard({l:'Toko kecil',v:fmtN(rows.length),note:`${rows.filter(r=>r.wil).length} di Air Dingin / Air Putih`,accent:'red'})+kpiCard({l:'Tanpa nomor HP',v:fmtN(rows.filter(r=>!phoneOf(r)).length),note:'perlu kunjungan langsung'});
  return`<div class="grid g4 mt">${k}<div class="card span2"><div class="lbl">Progress follow-up · klik untuk filter</div>${hbars(FU_ST.filter(s=>st[s]).map(s=>({k:s,l:s,v:st[s],c:FU_COL[FU_CLS[s]],vl:`${st[s]} · ${pct(st[s]/n,0)}`})),{max:n,act:'pfu'})}</div></div>${extra}`}
function projCols(P,sub){
  if(P==='loy')return[['ratio','Status target',r=>`<span class="tag ${r.stc}">${esc(r.st)}</span>`],['ach',`Capai s/d ${fmtDs(D.M.loy.asOf)}`,r=>`<b>${fmtS(r.ach)}</b><div class="mut">${pct(r.achPct,0)} dari ${fmtS(r.target)}</div><div class="prog sm"><div style="width:${Math.min(100,r.achPct*100)}%;background:${{good:'#0ca30c',warn:'#eda100',serious:'#ec835a',crit:'#d03b3b'}[r.stc]}"></div></div>`,'num'],['gap','Kurang / hari',r=>r.gapDay>0?fmtS(r.gapDay):'<span class="tag good">✓ aman</span>','num'],['chg','vs Sept',r=>`<span class="${r.chg<0?'neg':'pos'}">${sgnPct(r.chg,0)}</span><div class="mut">hadiah ${r.hadiah} ctn</div>`,'num']];
  if(P==='map'||(P==='klik'&&sub==='map'))return[['ts','Hasil / alasan',r=>`<span class="tag" style="background:#f4f3f0"><i class="dot" style="background:${CAT[r.cat].c}"></i> ${esc(CAT[r.cat].l)}</span><div class="mut clamp">${esc(r.alasan)}</div><div class="mut">${fmtD(r.ts)}</div>${r.kecilSrc?`<div class="mut small">Asal: ${esc(r.kecilSrc.join(' · '))}</div>`:''}`]];
  if(P==='klik'&&sub==='turun'){const nd=(D.M.ktr&&D.M.ktr.nd)||'';return[['chg','Sep → Okt',r=>`<b>${fmtS(r.sSep)} → ${fmtS(r.sOkt)}</b><div class="neg">${sgnPct(r.chg,0)} · ${fmtS(r.drop)}</div><div class="mut">Agu ${fmtS(r.sAug)}</div>`,'num'],['nov',`Nov 1–${nd}`,r=>`<b>${fmtS(r.novGross)}</b><div class="mut">proyeksi ${fmtS(r.novProj)}</div><span class="tag ${KT_CLS[r.ktSt]}">${KT_LBL[r.ktSt]}</span>`,'num'],['last','Kunjungan terakhir',r=>`${fmtD(r.upd||r.last)}`]]}
  if(P==='zb')return[['last','Segmentasi',r=>`<b>${esc(r.tier||'–')}</b><div class="mut">belanja terakhir ${fmtD(r.last)}</div>`]];
  if(P==='lms')return[['nov','Status promo',r=>`<span class="tag ${r.eligible?'good':r.back?'warn':'crit'}">${esc(lmsLabel(r))}</span><div class="mut">${r.back?`${fmtS(r.novGross)} · ${r.novStruk} struk · s/d tgl ${r.novLastDay}`:r.novGross>0?`belanja 1–2 Nov ${fmtS(r.novGross)} (sebelum promo)`:'belum ada belanja Nov'}</div>`,'' ],['last','Sleeper',r=>`<b>${esc(title(r.jenis))}</b><div class="mut">terakhir ${fmtD(r.lastBefore)} · ${fmtN(r.kgo)} kunj. sejak GO</div>`]];
  if(P==='svy')return[['age','Menunggu',r=>`<span class="tag ${r.age>30?'crit':r.age>14?'serious':'warn'}">${r.age} hari</span><div class="mut">daftar ${fmtD(r.daftar)} · ${esc(r.jenis)}</div>`],['note','Ket. survey',r=>`${r.size==='KECIL'?'<span class="tag warn">toko kecil → tawarkan Klik</span>':r.size==='BESAR'?'<span class="tag">toko besar</span>':''}<div class="mut">${esc(r.note)}</div>`]];
  return[['last','Belanja terakhir',r=>`${fmtD(r.last)}<div class="mut">${r.back?'<span class="tag good">✓ sudah belanja lagi</span>':r.days+' hari lalu'}</div>`],['kgo','Kunj. sejak GO',r=>fmtN(r.kgo),'num']];
}
function projTable(P,sub,rows){const f=F('project');const size=50;const page=Math.min(f.page||0,Math.max(0,Math.ceil(rows.length/size)-1));const sl=rows.slice(page*size,(page+1)*size);const cols=projCols(P,sub);
  const allSel=sl.length&&sl.every(r=>S.sel.has(r.id));
  return`${bulkBar('project',rows.length)}<div class="tbl-wrap"><table class="tbl"><thead><tr><th class="cb"><input type="checkbox" data-act="sel-page" ${allSel?'checked':''}></th>${sortTh('project','name','Member / toko')}${cols.map(c=>sortTh('project',c[0],c[1],c[3]||'')).join('')}<th>Lokasi</th>${P==='zb'?'<th>Kontak</th>'+sortTh('project','zst','Status undangan')+'<th>Catatan</th>':sortTh('project','vis','Status kunjungan')+'<th>Catatan / kendala</th>'}<th class="num">Aksi</th></tr></thead><tbody>
  ${sl.map(r=>`<tr class="${S.sel.has(r.id)?'sel':''}"><td class="cb"><input type="checkbox" data-act="sel" data-id="${r.id}" ${S.sel.has(r.id)?'checked':''}></td><td><div class="mc"><span class="av" style="background:${avCol(r.name)}">${esc(initials(r.name))}</span><div><button class="lnk nm" data-act="mem" data-id="${r.id}">${esc(r.name)}</button><div class="mut">${esc([r.code,r.sub&&'Sub '+r.sub,r.kel].filter(Boolean).join(' · '))}</div></div></div></td>
   ${cols.map(c=>`<td class="${c[3]||''}">${c[2](r)}</td>`).join('')}
   <td>${coordOf(r)?`<a class="btn sm" href="${gmapsPt(coordOf(r))}" target="_blank" rel="noopener" data-tip="Buka titik member di Google Maps">${IC.pin} Google Maps</a>${r.kel?`<div class="mut">${esc(r.kel)}</div>`:''}`:(r.addr?`<a class="btn sm" href="${typeof zbFind==='function'?zbFind(r):'#'}" target="_blank" rel="noopener" data-tip="${esc(zbAddr(r))}">${IC.pin} Cari alamat</a><div class="mut small">belum ada titik</div>`:`<span class="mut">Belum ada titik</span>`)}</td>
   ${P==='zb'?zbCells(r):visCells(r)}<td class="num">${actBtns(r,{rkm:false,pin:false})}</td></tr>`).join('')||'<tr><td colspan="13" class="empty">Tidak ada data untuk filter ini.</td></tr>'}</tbody></table></div>${pager('project',rows.length,page,size)}<datalist id="picList">${(S._projPics&&S._projPics.length?S._projPics:D.M.pics).map(p=>`<option value="${esc(p)}">`).join('')}</datalist>`}

/* ===== KUNJUNGAN MR ===== */
function vKunjungan(){const f=F('kunjungan');let rows=D.rkm;const months=countBy(D.rkm,r=>r.date.slice(0,7));
  if(f.pic)rows=rows.filter(r=>U(r.pic)===f.pic);if(f.type)rows=rows.filter(r=>r.type===f.type);if(f.mon)rows=rows.filter(r=>r.date.startsWith(f.mon));if(f.kd)rows=rows.filter(r=>String(r.issues).includes(f.kd));
  if(f.q){const q=f.q.toLowerCase();rows=rows.filter(r=>(r.name+' '+r.code+' '+r.notes+' '+r.issues+' '+r.pic).toLowerCase().includes(q))}
  rows=[...rows].sort((a,b)=>b.date.localeCompare(a.date));const kd=kendalaCount(rows);const byPic=countBy(rows,r=>title(r.pic));const types=countBy(D.rkm,r=>r.type);
  // kendala x status sekarang
  const ks={};rows.forEach(r=>{const rr=R(r.code);if(!rr)return;String(r.issues).split(/,\s*(?=\d)/).forEach(x=>{const k=x.replace(/^\s*\d+\s*\.\s*/,'').trim();if(!k)return;const o=ks[k]=ks[k]||{n:0,aktif:0,turun:0,sleeper:0};o.n++;if(rr.cur>0)o.aktif++;if(rr.st==='turun')o.turun++;if(rr.st==='sleeper')o.sleeper++})});
  const page=f.page||0,size=25;const sl=rows.slice(page*size,(page+1)*size);const matched=new Set(D.rkm.filter(r=>D.byCode[U(r.code)]).map(r=>U(r.code))).size;
  return pageHead('Kunjungan MR',`Catatan RKM per ${fmtD(toDate(D.agg.rkmAsOf))}: kendala, advisor dan hasil kunjungan`,`<button class="btn pri" data-act="form" data-k="rkm">✎ Isi RKM</button><button class="btn" data-act="x-xls">${IC.xls} Excel</button><button class="btn" data-act="x-ppt">${IC.ppt} PPT kendala</button>`)
  +`<div class="grid g4">${kpiCard({l:'Catatan kunjungan',v:fmtN(rows.length),note:`dari ${fmtN(D.rkm.length)} catatan`,accent:'red'})}${kpiCard({l:'Member cocok database',v:fmtN(matched),note:'kode ditemukan di master'})}${kpiCard({l:'Advisor tercatat',v:fmtN(Object.keys(countBy(D.rkm,r=>r.pic)).length),note:'nama advisor di RKM'})}${kpiCard({l:'Kembali aktif setelah dikunjungi',v:fmtN(new Set(rows.filter(r=>{const rr=R(r.code);return rr&&rr.cur>0}).map(r=>r.code)).size),note:'belanja di '+periodLabel(CALC.p,true)})}</div>
  <div class="grid g3 mt"><div class="card"><h3>Kendala tercatat</h3><p class="sub">Klik untuk filter catatan</p>${hbars(kd.slice(0,10).map(([k,n])=>({k,l:k,v:n,c:f.kd===k?'#c8102e':'#eb6834'})),{act:'kendala'})}</div>
   <div class="card"><h3>Kunjungan per advisor</h3><p class="sub">Klik untuk filter</p>${hbars(Object.entries(byPic).sort((a,b)=>b[1]-a[1]).map(([k,n])=>({k:U(k),l:k,v:n,c:picColor(U(k))})),{act:'kjpic'})}</div>
   <div class="card"><h3>Kunjungan per bulan</h3><p class="sub">Klik bulan untuk filter</p>${hbars(Object.entries(months).sort().map(([k,n])=>({k,l:periodLabel(D.periods.indexOf(k))||k,v:n,c:f.mon===k?'#c8102e':'#2a78d6'})),{act:'kjmon',lw:'45%'})}</div></div>
  <div class="card mt"><h3>Kendala × kondisi member sekarang</h3><p class="sub">Apakah member yang punya kendala tertentu sudah belanja lagi di ${periodLabel(CALC.p)}?</p><div class="tbl-wrap flat"><table class="tbl"><thead><tr><th>Kendala</th><th class="num">Catatan</th><th class="num">Belanja periode ini</th><th class="num">Sales turun</th><th class="num">Sleeper</th></tr></thead><tbody>${Object.entries(ks).sort((a,b)=>b[1].n-a[1].n).slice(0,12).map(([k,o])=>`<tr class="click" data-act="kendala" data-k="${esc(k)}"><td>${esc(k)}</td><td class="num">${o.n}</td><td class="num">${o.aktif} <span class="mut">(${pct(o.aktif/o.n,0)})</span></td><td class="num">${o.turun}</td><td class="num">${o.sleeper}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="fbar mt"><input class="search" placeholder="Cari member, kode, catatan, kendala…" data-act="fq" data-v="kunjungan" value="${esc(f.q||'')}">${selectF('kunjungan.pic','Advisor',[{v:'',l:'Semua'},...Object.keys(countBy(D.rkm,r=>U(r.pic))).sort().map(p=>({v:p,l:title(p)}))],f.pic)}${selectF('kunjungan.type','Tipe',[{v:'',l:'Semua'},...Object.entries(types).map(([k,n])=>({v:k,l:`${title(k)} (${n})`}))],f.type)}${f.kd||f.mon?`<span class="tag red">${esc([f.kd,f.mon&&periodLabel(D.periods.indexOf(f.mon))].filter(Boolean).join(' · '))} <button class="lnk" data-act="kj-clear">✕</button></span>`:''}</div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Tanggal / advisor</th><th>Member</th><th>Kendala</th><th style="width:40%">Keterangan kunjungan</th><th>Sales sekarang</th><th class="num">Aksi</th></tr></thead><tbody>${sl.map(r=>{const m=D.byCode[U(r.code)];const rr=m&&R(r.code);const e=m?memEntOf(m):null;
   return`<tr><td><b>${fmtD(toDate(r.date))}</b><div class="mut">${esc(title(r.pic))} · ${esc(title(r.type))}</div></td><td>${m?memCell(m):`<div class="nm">${esc(r.name)}</div><div class="mut">${esc(r.code)} · tidak cocok master</div>`}</td><td>${String(r.issues).split(/,\s*(?=\d)/).map(x=>`<span class="tag neu">${esc(x.replace(/^\s*\d+\s*\.\s*/,''))}</span>`).join(' ')}</td><td><div class="clamp3" data-tip="${esc(r.notes)}">${esc(r.notes)}</div></td><td>${rr?`${stTag(rr.st)}<div class="mut">${fmtS(rr.cur)}</div>`:'–'}</td><td class="num">${e?actBtns(e):''}</td></tr>`}).join('')}</tbody></table></div>${pager('kunjungan',rows.length,page,size)}`;
}

/* ===== TINDAK LANJUT ===== */
function vTindak(){const f=F('tindak');const all=new Map();Object.values(D.M.byId).forEach(e=>{if(e.src!=='SVY'||e.pending)all.set(e.id,e)});Object.keys(S.fu).forEach(id=>{if(!all.has(id)){const e=entOf(id);if(e)all.set(id,e)}});
  let rows=[...all.values()];const pics=countBy(rows,picOf);
  const board={};rows.forEach(e=>{const p=picOf(e)||'(belum ada PIC)';const s=statusOf(e);const o=board[p]=board[p]||{n:0,done:0,ok:0,today:0};o.n++;if(s!=='Belum dihubungi')o.done++;if(s==='Berhasil')o.ok++;const at=fuOf(e.id).at;if(at&&at.slice(0,10)===iso(TODAY))o.today++});
  if(f.pic)rows=rows.filter(e=>(picOf(e)||'(belum ada PIC)')===f.pic);if(f.st)rows=rows.filter(e=>statusOf(e)===f.st);if(f.pj)rows=rows.filter(e=>(D.M.projOf[e.id]||['Lainnya']).some(t=>t.startsWith(f.pj)));
  if(f.upd==='today')rows=rows.filter(e=>(fuOf(e.id).at||'').slice(0,10)===iso(TODAY));if(f.upd==='janji')rows=rows.filter(e=>fuOf(e.id).due);
  if(f.q){const q=f.q.toLowerCase();rows=rows.filter(e=>(e.name+' '+(e.code||'')+' '+(fuOf(e.id).note||'')).toLowerCase().includes(q))}
  rows.sort((a,b)=>(fuOf(b.id).at||'').localeCompare(fuOf(a.id).at||'')||a.name.localeCompare(b.name));
  const stc=countBy(rows,statusOf);const page=f.page||0,size=50;const sl=rows.slice(page*size,(page+1)*size);const due=rows.filter(e=>fuOf(e.id).due&&fuOf(e.id).due<=iso(TODAY)&&!['Berhasil','Tidak berminat'].includes(statusOf(e)));
  return pageHead('Tindak lanjut',`Semua member & toko di project + semua yang punya catatan follow-up · ${fmtN(all.size)} baris`,`<button class="btn" data-act="x-xls">${IC.xls} Excel (bisa diisi & upload balik)</button><button class="btn" data-act="report">Laporan WA grup</button>`)
  +`${due.length?`<div class="alert red">⏰ ${due.length} janji follow-up jatuh tempo hari ini atau terlewat. <button class="lnk" data-act="fset" data-v="tindak.upd" data-k="janji">Lihat</button></div>`:''}
  <div class="card mt"><h3>Papan PIC</h3><p class="sub">Klik PIC untuk melihat daftarnya</p><div class="tbl-wrap flat"><table class="tbl"><thead><tr><th>PIC</th><th class="num">Ditugaskan</th><th class="num">Sudah ditindaklanjuti</th><th style="width:30%">Progress</th><th class="num">Berhasil</th><th class="num">Update hari ini</th></tr></thead><tbody>${Object.entries(board).sort((a,b)=>b[1].n-a[1].n).map(([p,o])=>`<tr class="click ${f.pic===p?'sel':''}" data-act="fset" data-v="tindak.pic" data-k="${esc(f.pic===p?'':p)}"><td><span class="dot" style="background:${picColor(p)}"></span> <b>${esc(title(p))}</b></td><td class="num">${o.n}</td><td class="num">${o.done}</td><td><div class="prog"><div style="width:${o.done/o.n*100}%"></div></div></td><td class="num">${o.ok}</td><td class="num">${o.today||''}</td></tr>`).join('')}</tbody></table></div></div>
  ${filterChips('tindak.st',[{k:'',l:'Semua status',n:rows.length},...FU_ST.filter(s=>stc[s]).map(s=>({k:s,l:s,n:stc[s],dot:FU_COL[FU_CLS[s]]}))],f.st||'')}
  <div class="fbar"><input class="search" placeholder="Cari nama, kode, catatan…" data-act="fq" data-v="tindak" value="${esc(f.q||'')}">${selectF('tindak.pj','Project',[{v:'',l:'Semua'},{v:'Loyalty Targetan',l:'Loyalty Targetan'},{v:'Loyalty MM Sleepers',l:'Loyalty MM Sleepers'},{v:'Mapping',l:'Mapping'},{v:'ACC',l:'ACC belum aktivasi'},{v:'Klik',l:'Klik'},{v:'Lainnya',l:'Di luar project'}],f.pj)}${selectF('tindak.upd','Update',[{v:'',l:'Semua'},{v:'today',l:'Diupdate hari ini'},{v:'janji',l:'Ada tanggal janji'}],f.upd)}</div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Member / toko</th><th>Project</th><th>PIC</th><th>Status</th><th>Janji</th><th>Catatan terakhir</th><th>Diupdate</th><th class="num">Aksi</th></tr></thead><tbody>${sl.map(e=>{const fu=fuOf(e.id);const s=statusOf(e);return`<tr><td><button class="lnk nm" data-act="mem" data-id="${e.id}">${esc(e.name)}</button><div class="mut">${esc([e.code,e.kel].filter(Boolean).join(' · '))}</div></td><td>${(D.M.projOf[e.id]||['Di luar project']).map(t=>`<span class="tag neu">${esc(t)}</span>`).join(' ')}</td><td>${esc(picLbl(picOf(e))||'–')}</td><td><span class="tag ${FU_CLS[s]}">${esc(s)}</span></td><td>${fu.due?`<span class="${fu.due<=iso(TODAY)?'neg':''}">${fmtD(toDate(fu.due))}</span>`:'–'}</td><td><div class="clamp">${esc(fu.note||'')}</div></td><td class="mut">${fu.at?new Date(fu.at).toLocaleString('id-ID',{dateStyle:'short',timeStyle:'short'}):''}</td><td class="num">${actBtns(e)}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Belum ada data.</td></tr>'}</tbody></table></div>${pager('tindak',rows.length,page,size)}`;
}

