  prod:{l:'Sales per produk (bulanan)',f:'Harian / mingguan',w:'File "SALES PER PRODUK MEMBER MERAH <BULAN> <TAHUN>" (kolom PLU, Deskripsi, Member, Struk, Qty, Gross, Margin).',dl:'Produk, Ringkasan'},
  loyalty:{l:'Monitoring Loyalty MM Pareto',f:'Harian (H-1)',w:'Sheet SALES ALL & SALES ROKOK terbaru; LIST MEMBER sekali di awal bulan.',dl:'Project 1'},
  sleepers:{l:'MM Sleepers setelah ongkir',f:'Harian',w:'Kolom UPT KUNJ. Selain itu sales master juga dicek otomatis.',dl:'Project 4 sub 1'},
